/**
 * Shim for `@deepseek-ai/dsh-llm`.
 *
 * The real seam uses exactly one export from it: `HarnessError`, as the base
 * class of `WebError`. The error *code* is what the selection algorithm is
 * asserted on, and that is set by this constructor. The body below is copied
 * verbatim from the real `lib/types/error.js` so the `name`/`code` semantics the
 * test asserts on are identical to production — in particular
 * `this.name = new.target.name`, which is what makes a `WebError` report itself
 * as `"WebError"` rather than `"HarnessError"`.
 */
export class HarnessError extends Error {
  code

  constructor(message, code, options) {
    super(message, options)
    this.code = code
    this.name = new.target.name
  }
}

export default { HarnessError }
